ee:message.ee:set-payload:
%dw 2.0
import * from dw::core::Strings
import * from dw::Runtime
output application/json
var validColumns = vars.colRows map (c) -> upper(c.column_name)
var colTypes = vars.colRows reduce ((c, acc = {}) -> acc ++ {(upper(c.column_name)): upper(c.data_type)})
fun isDateLike(col) = ((colTypes[col] default "") contains "DATE") or ((colTypes[col] default "") contains "TIMESTAMP")
var reserved = ["ORDERBY", "ORDERDIR", "LIMIT"]
var qp = attributes.queryParams default {}
var filterEntries = (namesOf(qp) filter ((k) -> (validColumns contains upper(k)) and !(reserved contains upper(k))))
    map ((k, i) -> { column: upper(k), bindName: "f" ++ (i as String), value: qp[k] as String })
var whereSql = if (isEmpty(filterEntries)) ""
    else " WHERE " ++ ((filterEntries map (f) -> "UPPER(TO_CHAR(" ++ f.column ++ ")) LIKE UPPER(:" ++ f.bindName ++ ")") joinBy " AND ")
var orderByRaw = upper(qp.orderBy default "")
var orderBy = if (validColumns contains orderByRaw) orderByRaw else validColumns[0]
var orderDir = if (upper(qp.orderDir default "DESC") == "ASC") "ASC" else "DESC"
var limitRaw = try(() -> (qp.limit default "200") as Number) orElse 200
var limitVal = if (limitRaw > 2000) 2000 else (if (limitRaw < 1) 1 else limitRaw)
// Explicit column list, not "SELECT *" — a date/timestamp column fetched via "SELECT *" comes
// back from Oracle's JDBC driver as its own proprietary internal representation (a byte-stream
// wrapper, not a usable date) rather than a plain value; TO_CHAR-ing it in the SQL itself makes
// Oracle do that conversion before the value ever reaches the driver boundary, sidestepping the
// problem entirely. Every column keeps its own name as its alias either way, so the result set's
// column labels stay exactly the real column names (still Oracle's native uppercase, matching
// validColumns) for the re-keying step below to work from.
var selectCols = validColumns map ((col) -> if (isDateLike(col)) ("TO_CHAR(" ++ col ++ ", 'YYYY-MM-DD HH24:MI:SS.FF3') " ++ col) else col)
---
{
    sql: "SELECT " ++ (selectCols joinBy ", ") ++ " FROM syskm.audit_log" ++ whereSql ++ " ORDER BY " ++ orderBy ++ " " ++ orderDir ++ " FETCH FIRST :alLimit ROWS ONLY",
    params: (filterEntries reduce ((f, acc = {}) -> acc ++ {(f.bindName): "%" ++ f.value ++ "%"})) ++ {alLimit: limitVal},
    orderBy: lower(orderBy),
    orderDir: orderDir,
    columnNames: validColumns
}
